327	// SubmitResult 是交易提交结果。
328	type SubmitResult struct {
329		// TxID 被接受交易的标识。
330		TxID string
331		// ReplacedID 若本次提交替换了旧交易，为旧交易标识；否则为空。
332		ReplacedID string
333		// EvictedID 若本次提交因池满挤出了旧交易，为被挤出交易的标识；否则为空。
334		EvictedID string
335	}
