472	// 额外拒绝原因。
473	const (
474		// ReasonProposalLocked 同发送者同序号交易已被未决候选引用，禁止替换。
475		ReasonProposalLocked = "tx-in-proposal"
476		// ReasonUnknownTx 查询的交易标识不存在。
477		ReasonUnknownTx = "unknown-transaction"
478		// ReasonUnknownBlock 查询的区块高度不存在。
479		ReasonUnknownBlock = "unknown-block"
480		// ReasonTxNotInPool 候选引用了已退出交易池的交易（已确认、被替换、已过期或被挤出）。
481		ReasonTxNotInPool = "tx-not-in-pool"
482		// ReasonDuplicateInList 候选列表中同一交易出现多次。
483		ReasonDuplicateInList = "duplicate-in-list"
484		// ReasonTooManyTxs 候选包含的交易超过单块上限。
485		ReasonTooManyTxs = "too-many-transactions"
486		// ReasonSequenceGap 候选中某账户的序号未从已确认序号加一开始连续递增。
487		ReasonSequenceGap = "sequence-not-consecutive"
488	)
