17	// fixedValidatorKey 生成确定性的第 i 个验证者公钥（32 字节，内容为 i*32+j+1）。
18	func fixedValidatorKey(i int) []byte {
19		b := make([]byte, 32)
20		for j := range b {
21			b[j] = byte(i*32 + j + 1)
22		}
23		return b
24	}
25	
26	// fixedValidators 返回 count 个确定性验证者公钥，顺序固定。
27	func fixedValidators(count int) [][]byte {
28		vals := make([][]byte, count)
29		for i := range vals {
30			vals[i] = fixedValidatorKey(i)
31		}
32		return vals
33	}
34	
35	// wantProposerByRule 在测试侧按 README 公开规则独立复算指定轮次的提议者，
36	// 不经过被检查的实现，用于交叉核对固定表之外的输入。
37	func wantProposerByRule(seed []byte, validators [][]byte, round uint64) []byte {
38		var buf [8]byte
39		binary.BigEndian.PutUint64(buf[:], round)
40		h := sha256.New()
41		h.Write(seed)
42		h.Write(buf[:])
43		sum := h.Sum(nil)
44		return validators[binary.BigEndian.Uint64(sum[:8])%uint64(len(validators))]
45	}
46	
47	// newProposerTestNode 用给定种子与验证者名单建节点。
48	func newProposerTestNode(t *testing.T, seed []byte, validators [][]byte) *Node {
49		t.Helper()
50		n, err := New(t.TempDir(), Config{Seed: seed, Validators: validators, MaxTxsPerBlock: 4})
51		if err != nil {
52			t.Fatal(err)
53		}
54		return n
55	}
56	
57	// assertProposer 断言 ProposerFor(round) 返回十六进制为 wantHex 的公钥，
58	// 并与测试侧按公开规则独立复算的结果交叉核对。
59	func assertProposer(t *testing.T, n *Node, seed []byte, validators [][]byte, round uint64, wantHex string) {
60		t.Helper()
61		want, err := hex.DecodeString(wantHex)
62		if err != nil {
63			t.Fatalf("bad test fixture hex: %v", err)
64		}
65		got := n.ProposerFor(round)
66		if string(got) != string(want) {
67			t.Fatalf("ProposerFor(%d) = %x, want pinned %s", round, got, wantHex)
68		}
69		if string(got) != string(wantProposerByRule(seed, validators, round)) {
70			t.Fatalf("ProposerFor(%d) = %x, independent rule computation gives %x", round, got, wantProposerByRule(seed, validators, round))
71		}
72	}
73	
74	// 固定种子 + 5 名验证者（非二的幂）+ 固定顺序：逐轮钉住提议者公钥。
75	// 覆盖首轮、255/256 跨字节边界、32 位整数边界与完整 uint64 轮次。
76	func TestProposerForPinnedKeys(t *testing.T) {
77		seed := []byte("proposer-regression-seed-v1")
78		validators := fixedValidators(5)
79		n := newProposerTestNode(t, seed, validators)
80	
81		cases := []struct {
82			round uint64
83			idx   int // 预期公钥在名单中的位置
84			hex   string
85		}{
86			{1, 1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
87			{2, 1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
88			{3, 2, "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60"},
89			// 255 -> 256 跨越大端编码的字节边界，截断或数值表示变化会在这里选错人。
90			{255, 4, "8182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9fa0"},
91			{256, 3, "6162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f80"},
92			{257, 2, "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60"},
93			// 32 位无符号整数边界：轮次必须按完整 uint64 参与选择。
94			{4294967295, 1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
95			{4294967296, 1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
