1	package consensus
2	
3	import (
4		"fmt"
5		"testing"
6	)
7	
8	// 本文件回归保障：Propose（首次产生与同轮重复请求）与 Proposal（直接读取）
9	// 返回的都是提议冻结时的独立结果。调用方交换交易次序、把交易标识改成未知标识、
10	// 增减列表项、改写轮次/区块标识/空块标记，都只能影响自己手中的这一份数据，
11	// 不能改变本轮已冻结的本地提议、候选集合、投票与确认结果。
12	
13	const (
14		// fakeTxID 是测试中调用方伪造的交易标识：从未提交进交易池。
15		fakeTxID = "fake-tx-id-never-submitted"
16		// fakeBlockID 是测试中调用方伪造的区块标识：从未登记为候选。
17		fakeBlockID = "fake-block-id-never-registered"
18	)
19	
20	// assertProposalView 校验提议视图与冻结时的取值完全一致：
21	// 轮次、区块标识、交易顺序与空块标记。
22	func assertProposalView(t *testing.T, p ProposalView, round uint64, blockID string, txIDs []string) {
23		t.Helper()
24		if p.Round != round || p.BlockID != blockID || fmt.Sprint(p.TxIDs) != fmt.Sprint(txIDs) {
25			t.Fatalf("proposal = round:%d block:%s empty:%v tx:%v; want round:%d block:%s empty:%v tx:%v",
26				p.Round, p.BlockID, p.Empty, p.TxIDs, round, blockID, len(txIDs) == 0, txIDs)
27		}
28		if p.Empty != (len(txIDs) == 0) {
29			t.Fatalf("proposal empty flag = %v, want %v", p.Empty, len(txIDs) == 0)
30		}
31	}
32	
33	// candidateByBlockID 在一轮候选视图中按区块标识查找候选，找不到返回 nil。
34	func candidateByBlockID(rc *RoundCandidates, blockID string) *CandidateView {
35		for i := range rc.Candidates {
36			if rc.Candidates[i].BlockID == blockID {
37				return &rc.Candidates[i]
38			}
39		}
40		return nil
41	}
42	
43	// tamperProposalView 以调用方身份尽力改写手中的提议视图：
44	// 交换前两项次序、追加未知交易标识、改写轮次与区块标识、翻转空块标记。
45	func tamperProposalView(p *ProposalView) {
46		if len(p.TxIDs) >= 2 {
47			p.TxIDs[0], p.TxIDs[1] = p.TxIDs[1], p.TxIDs[0]
48		}
49		p.TxIDs = append(p.TxIDs, fakeTxID)
50		p.Round += 70000
51		p.BlockID = fakeBlockID
52		p.Empty = !p.Empty
53	}
54	
55	// setupProposalCopyNode 准备一个含三笔交易的节点：甲序号 1 费用 30、
56	// 甲序号 2 费用 100、乙序号 1 费用 50。按跨账户打包规则，本地提议的
57	// 固定顺序为 [乙1, 甲1, 甲2]，上限 4 时全部选入。
58	func setupProposalCopyNode(t *testing.T) (*Node, string, []testKey, []string) {
59		t.Helper()
60		keys := genKeys(t, 4)
61		n, dir := newTestNode(t, keys, 4)
62		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 30, 100)
63		a2 := NewTransaction(keys[0].priv, 2, []byte("a2"), 100, 100)
64		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 50, 100)
65		for _, tx := range []*Transaction{a1, a2, b1} {
66			if _, err := n.Submit(tx); err != nil {
67				t.Fatal(err)
68			}
69		}
70		return n, dir, keys, []string{b1.ID(), a1.ID(), a2.ID()}
71	}
72	
73	// 三个入口——首次 Propose、同轮再次 Propose、直接读取 Proposal——返回的
74	// 都是取得时的独立结果：编辑其中一份只能影响这一份数据；本轮已冻结的本地
75	// 提议的交易集合、次序、区块标识与空块标记保持原样，先前取得未编辑的结果
76	// 也保持原样，之后再次读取仍得到冻结时的提议。
77	func TestProposalResultsAreIndependentCopies(t *testing.T) {
78		n, dir, keys, want := setupProposalCopyNode(t)
79		wantBlockID := BlockID(1, 1, "", want)
80	
81		// 三个入口各取得一份结果。
82		first, err := n.Propose()
83		if err != nil {
84			t.Fatal(err)
85		}
86		assertProposalView(t, first, 1, wantBlockID, want)
87		second, err := n.Propose()
88		if err != nil {
89			t.Fatal(err)
90		}
91		assertProposalView(t, second, 1, wantBlockID, want)
92		third, ok := n.Proposal()
93		if !ok {
94			t.Fatal("Proposal should exist after Propose")
95		}
96		assertProposalView(t, third, 1, wantBlockID, want)
97	
98		// 尽力改写第一份：交换次序、追加未知标识、改轮次与区块标识、翻转空块标记。
99		tamperProposalView(&first)
100		// 另外两份已取得但未编辑的结果保持冻结时的原样。
101		assertProposalView(t, second, 1, wantBlockID, want)
102		assertProposalView(t, third, 1, wantBlockID, want)
103	
104		// 再把第二份改成未知标识并缩短长度，第三份与之后新取得的结果仍是原提议。
105		second.TxIDs[0] = fakeTxID
106		second.TxIDs = second.TxIDs[:1]
107		assertProposalView(t, third, 1, wantBlockID, want)
108		fourth, ok := n.Proposal()
109		if !ok {
110			t.Fatal("Proposal should still exist")
111		}
112		assertProposalView(t, fourth, 1, wantBlockID, want)
113		fifth, err := n.Propose()
114		if err != nil {
115			t.Fatal(err)
116		}
117		assertProposalView(t, fifth, 1, wantBlockID, want)
118	
119		// 节点保存的原始交易仍按原顺序等待投票，伪造标识不在交易池中。
120		assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{
121			want[1]: "waiting-vote", want[2]: "waiting-vote",
122		})
123		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{
124			want[0]: "waiting-vote",
125		})
126		if _, err := n.Tx(fakeTxID); reason(err) != ReasonUnknownTx {
127			t.Fatalf("fake tx lookup got %v, want %s", err, ReasonUnknownTx)
128		}
129	
130		// 登记一个合法竞争候选（甲1、乙1，顺序与本地提议不同）不改变本地提议；
131		// 调用方伪造的交易标识不能登记成候选，伪造的区块标识也不是候选。
132		alt, err := n.RegisterCandidate(1, []string{want[1], want[0]})
133		if err != nil {
134			t.Fatal(err)
135		}
136		if alt.Existing || alt.BlockID == wantBlockID {
137			t.Fatalf("competing candidate registration wrong: %+v", alt)
138		}
139		if _, err := n.RegisterCandidate(1, []string{fakeTxID}); reason(err) != ReasonUnknownTx {
140			t.Fatalf("register fake tx id got %v, want %s", err, ReasonUnknownTx)
141		}
142		rc, err := n.Candidates(1)
143		if err != nil {
144			t.Fatal(err)
145		}
146		local := candidateByBlockID(rc, wantBlockID)
147		if local == nil || !local.Local || local.Result != CandidatePending ||
148			fmt.Sprint(local.TxIDs) != fmt.Sprint(want) {
149			t.Fatalf("local candidate changed by caller edits: %+v", local)
150		}
151		if c := candidateByBlockID(rc, alt.BlockID); c == nil || c.Local ||
152			fmt.Sprint(c.TxIDs) != fmt.Sprint([]string{want[1], want[0]}) || c.Result != CandidatePending {
153			t.Fatalf("competing candidate wrong after caller edits: %+v", c)
154		}
155		if candidateByBlockID(rc, fakeBlockID) != nil {
156			t.Fatal("fake block id must not be a registered candidate")
157		}
158	
159		// 对原区块标识正常投票：前两票计入但不确认。
160		r0, err := n.Vote(keys[0].pub, 1, wantBlockID)
161		if err != nil {
162			t.Fatal(err)
163		}
164		if !r0.Counted || r0.Confirmed {
165			t.Fatalf("first vote = %+v, want counted without confirm", r0)
166		}
167		if _, err := n.Vote(keys[1].pub, 1, wantBlockID); err != nil {
168			t.Fatal(err)
169		}
170		if c := candidateByBlockID(mustCandidates(t, n, 1), wantBlockID); len(c.Voters) != 2 {
171			t.Fatalf("local candidate votes = %d, want 2", len(c.Voters))
172		}
173	
174		// 向手中结果里被改写的区块标识投票：按已有规则以 wrong-block-id 拒绝，
175		// 不占用该验证者本轮的投票，也不计入真实候选的票数。
176		if _, err := n.Vote(keys[2].pub, 1, fakeBlockID); reason(err) != ReasonWrongBlock {
177			t.Fatalf("vote for fake block id got %v, want %s", err, ReasonWrongBlock)
178		}
179		if c := candidateByBlockID(mustCandidates(t, n, 1), wantBlockID); len(c.Voters) != 2 {
180			t.Fatalf("rejected vote must not count: local candidate votes = %d, want 2", len(c.Voters))
181		}
182	
183		// 被拒绝的验证者仍可对真实候选投票，第三票严格超过 2/3 并立即确认。
184		res, err := n.Vote(keys[2].pub, 1, wantBlockID)
185		if err != nil {
186			t.Fatal(err)
187		}
188		if !res.Confirmed || res.Block == nil {
189			t.Fatalf("third vote = %+v, want confirmation", res)
190		}
191	
192		// 确认块仍使用原来的区块标识与原始交易顺序，接在空的前块标识之后。
193		assertBlock(t, *res.Block, want, 1, 1, wantBlockID, "")
194		if n.CurrentRound() != 2 || n.Height() != 1 {
195			t.Fatalf("state after confirm: round=%d height=%d, want round=2 height=1",
196				n.CurrentRound(), n.Height())
197		}
198		blk, err := n.BlockAt(1)
199		if err != nil {
200			t.Fatal(err)
201		}
202		assertBlock(t, blk, want, 1, 1, wantBlockID, "")
203		latest, ok := n.LatestBlock()
204		if !ok {
205			t.Fatal("latest block should exist")
206		}
207		assertBlock(t, latest, want, 1, 1, wantBlockID, "")
208	
209		// 交易查询关联到实际确认块；账户已确认序号按真实选入的交易推进。
210		for _, id := range want {
211			info, err := n.Tx(id)
212			if err != nil {
213				t.Fatal(err)
214			}
215			if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != wantBlockID {
216				t.Fatalf("tx %s confirmation link wrong: %+v", id, info)
217			}
218		}
219		if acct := n.Account(keys[0].pub); acct.ConfirmedSequence != 2 || len(acct.Pending) != 0 {
220			t.Fatalf("sender a confirmed seq = %d pending = %d, want 2/0", acct.ConfirmedSequence, len(acct.Pending))
221		}
222		if acct := n.Account(keys[1].pub); acct.ConfirmedSequence != 1 || len(acct.Pending) != 0 {
223			t.Fatalf("sender b confirmed seq = %d pending = %d, want 1/0", acct.ConfirmedSequence, len(acct.Pending))
224		}
225	
226		// 候选结果：本地提议按原顺序胜出，竞争候选落选，轮次确认为投票确认。
227		rcEnd, err := n.Candidates(1)
228		if err != nil {
229			t.Fatal(err)
230		}
231		if c := candidateByBlockID(rcEnd, wantBlockID); c == nil || c.Result != CandidateWon || !c.Local ||
232			fmt.Sprint(c.TxIDs) != fmt.Sprint(want) {
233			t.Fatalf("winner candidate wrong: %+v", c)
234		}
235		if c := candidateByBlockID(rcEnd, alt.BlockID); c == nil || c.Result != CandidateLost {
236			t.Fatalf("competing candidate should be lost: %+v", c)
237		}
238		if !rcEnd.Ended || rcEnd.UnconfirmedEnd {
239			t.Fatalf("round 1 ending wrong: ended=%v unconfirmed=%v", rcEnd.Ended, rcEnd.UnconfirmedEnd)
240		}
241	
242		// 早先取得、从未编辑的那份结果始终保持冻结时的原样。
243		assertProposalView(t, third, 1, wantBlockID, want)
244	
245		// 确认时的保存发生在调用方篡改之后：重开状态目录，篡改的标识与顺序
246		// 都不能落盘，确认历史仍是原来的区块标识与交易顺序。
247		reopened, err := Open(dir)
248		if err != nil {
249			t.Fatal(err)
250		}
251		stored, err := reopened.BlockAt(1)
252		if err != nil {
253			t.Fatal(err)
254		}
255		assertBlock(t, stored, want, 1, 1, wantBlockID, "")
256		rcStored, err := reopened.Candidates(1)
257		if err != nil {
258			t.Fatal(err)
259		}
260		if c := candidateByBlockID(rcStored, wantBlockID); c == nil || c.Result != CandidateWon ||
261			fmt.Sprint(c.TxIDs) != fmt.Sprint(want) {
262			t.Fatalf("stored winner wrong after reopen: %+v", c)
263		}
264		if candidateByBlockID(rcStored, fakeBlockID) != nil {
265			t.Fatal("fake block id must not be persisted as a candidate")
266		}
267		if _, err := reopened.Tx(fakeTxID); reason(err) != ReasonUnknownTx {
268			t.Fatalf("fake tx id persisted: %v", err)
269		}
270	}
271	
272	// mustCandidates 查询本轮候选，查询失败时终止测试。
273	func mustCandidates(t *testing.T, n *Node, round uint64) *RoundCandidates {
274		t.Helper()
275		rc, err := n.Candidates(round)
276		if err != nil {
277			t.Fatal(err)
278		}
279		return rc
280	}
281	
282	// 各类编辑方式分别回归：交换次序、单项改成未知标识、删除/插入/追加列表项、
283	// 清空列表、翻转空块标记、改写轮次与区块标识。每一种修改后，三个入口再次
284	// 读取都仍返回冻结的原提议，本地候选保持原交易集合、顺序与区块标识等待投票，
285	// 伪造标识既不是池内交易，也不能登记为候选，原始交易仍处于等待投票状态。
286	func TestProposalResultEditVariantsStayLocal(t *testing.T) {
287		variants := []struct {
288			name string
289			edit func(p *ProposalView)
290		}{
291			{"swap order", func(p *ProposalView) {
292				p.TxIDs[0], p.TxIDs[2] = p.TxIDs[2], p.TxIDs[0]
293			}},
294			{"replace item with unknown id", func(p *ProposalView) {
295				p.TxIDs[1] = fakeTxID
296			}},
297			{"remove item", func(p *ProposalView) {
298				p.TxIDs = p.TxIDs[:1]
299			}},
300			{"append unknown id", func(p *ProposalView) {
301				p.TxIDs = append(p.TxIDs, fakeTxID)
302			}},
303			{"insert unknown id at front", func(p *ProposalView) {
304				p.TxIDs = append([]string{fakeTxID}, p.TxIDs...)
305			}},
306			{"clear list", func(p *ProposalView) {
307				p.TxIDs = nil
308			}},
309			{"flip empty flag", func(p *ProposalView) {
310				p.Empty = true
311			}},
312			{"rewrite round and block id", func(p *ProposalView) {
313				p.Round = 999
314				p.BlockID = fakeBlockID
315			}},
316		}
317		for _, v := range variants {
318			t.Run(v.name, func(t *testing.T) {
319				n, _, _, want := setupProposalCopyNode(t)
320				wantBlockID := BlockID(1, 1, "", want)
321	
322				p, err := n.Propose()
323				if err != nil {
324					t.Fatal(err)
325				}
326				// 另取一份结果保留在手中：它不应被本次编辑波及。
327				held, ok := n.Proposal()
328				if !ok {
329					t.Fatal("Proposal should exist")
330				}
331	
332				v.edit(&p)
333	
334				// 直接读取、同轮再次请求与先取得未编辑的那份，全部仍是原提议。
335				again, ok := n.Proposal()
336				if !ok {
337					t.Fatal("Proposal should still exist")
338				}
339				assertProposalView(t, again, 1, wantBlockID, want)
340				repeated, err := n.Propose()
341				if err != nil {
342					t.Fatal(err)
343				}
344				assertProposalView(t, repeated, 1, wantBlockID, want)
345				assertProposalView(t, held, 1, wantBlockID, want)
346	
347				// 本地候选的交易集合、顺序与区块标识不变，仍处于等待投票状态。
348				c := candidateByBlockID(mustCandidates(t, n, 1), wantBlockID)
349				if c == nil || !c.Local || c.Result != CandidatePending ||
350					fmt.Sprint(c.TxIDs) != fmt.Sprint(want) {
351					t.Fatalf("local candidate changed by %q edit: %+v", v.name, c)
352				}
353				// 伪造标识既不是池内交易，也不能借调用方手中的列表登记为候选。
354				if _, err := n.Tx(fakeTxID); reason(err) != ReasonUnknownTx {
355					t.Fatalf("fake tx lookup after %q edit got %v, want %s", v.name, err, ReasonUnknownTx)
356				}
357				if _, err := n.RegisterCandidate(1, []string{fakeTxID}); reason(err) != ReasonUnknownTx {
358					t.Fatalf("register fake tx after %q edit got %v, want %s", v.name, err, ReasonUnknownTx)
359				}
360				// 原始交易仍属于本轮本地提议、等待投票。
361				for _, id := range want {
362					info, err := n.Tx(id)
363					if err != nil {
364						t.Fatalf("tx %s lookup after %q edit: %v", id, v.name, err)
365					}
366					if info.Status != StatusProposed {
367						t.Fatalf("tx %s status after %q edit = %s, want %s", id, v.name, info.Status, StatusProposed)
368					}
369				}
370			})
371		}
372	}
373	
374	// 空块提议同样返回独立结果：调用方向空交易列表追加标识、翻转空块标记、
375	// 改写区块标识后，再次读取仍显示零交易空块；候选查询中的本地候选仍是
376	// pending 空块；对原区块标识正常投票确认，得到的确认块仍没有交易，
377	// 且篡改不会随确认保存落盘。
378	func TestEmptyProposalResultEditStaysEmpty(t *testing.T) {
379		keys := genKeys(t, 4)
380		n, dir := newTestNode(t, keys, 4)
381	
382		first, err := n.Propose() // 空池只能产生空块。
383		if err != nil {
384			t.Fatal(err)
385		}
386		wantBlockID := BlockID(1, 1, "", []string{})
387		assertProposalView(t, first, 1, wantBlockID, []string{})
388		second, err := n.Propose()
389		if err != nil {
390			t.Fatal(err)
391		}
392		third, ok := n.Proposal()
393		if !ok {
394			t.Fatal("empty Proposal should exist")
395		}
396	
397		// 调用方向返回的空列表追加标识，并翻转空块标记、改写区块标识与轮次。
398		first.TxIDs = append(first.TxIDs, fakeTxID)
399		first.Empty = false
400		first.BlockID = fakeBlockID
401		first.Round = 888
402	
403		// 其他已取得的结果与之后再次读取的结果仍是零交易空块。
404		assertProposalView(t, second, 1, wantBlockID, []string{})
405		assertProposalView(t, third, 1, wantBlockID, []string{})
406		fourth, ok := n.Proposal()
407		if !ok {
408			t.Fatal("empty Proposal should still exist")
409		}
410		assertProposalView(t, fourth, 1, wantBlockID, []string{})
411		repeated, err := n.Propose()
412		if err != nil {
413			t.Fatal(err)
414		}
415		assertProposalView(t, repeated, 1, wantBlockID, []string{})
416	
417		// 候选查询中的本地候选仍是零交易空块、等待投票；伪造标识既非交易也非候选。
418		c := candidateByBlockID(mustCandidates(t, n, 1), wantBlockID)
419		if c == nil || !c.Local || c.Result != CandidatePending || len(c.TxIDs) != 0 {
420			t.Fatalf("empty local candidate wrong after edit: %+v", c)
421		}
422		if _, err := n.Tx(fakeTxID); reason(err) != ReasonUnknownTx {
423			t.Fatalf("fake tx lookup got %v, want %s", err, ReasonUnknownTx)
424		}
425		if _, err := n.RegisterCandidate(1, []string{fakeTxID}); reason(err) != ReasonUnknownTx {
426			t.Fatalf("register fake tx got %v, want %s", err, ReasonUnknownTx)
427		}
428		if candidateByBlockID(mustCandidates(t, n, 1), fakeBlockID) != nil {
429			t.Fatal("fake block id must not be registered as candidate")
430		}
431	
432		// 向伪造的区块标识投票按已有规则拒绝，不计票也不锁定验证者。
433		if _, err := n.Vote(keys[0].pub, 1, fakeBlockID); reason(err) != ReasonWrongBlock {
434			t.Fatalf("vote fake empty-block id got %v, want %s", err, ReasonWrongBlock)
435		}
436	
437		// 对原空块标识投票达到现有确认条件，确认块仍是零交易的空块。
438		confirmByVotes(t, n, keys, wantBlockID)
439		blk, err := n.BlockAt(1)
440		if err != nil {
441			t.Fatal(err)
442		}
443		if len(blk.TxIDs) != 0 || blk.ID != wantBlockID || blk.Height != 1 || blk.Round != 1 {
444			t.Fatalf("confirmed empty block wrong: %+v", blk)
445		}
446		if n.Height() != 1 {
447			t.Fatalf("height = %d, want 1", n.Height())
448		}
449	
450		// 重开后历史仍是零交易空块，伪造标识没有落盘。
451		reopened, err := Open(dir)
452		if err != nil {
453			t.Fatal(err)
454		}
455		stored, err := reopened.BlockAt(1)
456		if err != nil {
457			t.Fatal(err)
458		}
459		if len(stored.TxIDs) != 0 || stored.ID != wantBlockID {
460			t.Fatalf("empty block changed after reopen: %+v", stored)
461		}
462		rc, err := reopened.Candidates(1)
463		if err != nil {
464			t.Fatal(err)
465		}
466		if c := candidateByBlockID(rc, wantBlockID); c == nil || c.Result != CandidateWon || len(c.TxIDs) != 0 {
467			t.Fatalf("stored empty candidate wrong: %+v", c)
468		}
469		if candidateByBlockID(rc, fakeBlockID) != nil {
470			t.Fatal("fake block id must not persist as candidate")
471		}
472		if _, err := reopened.Tx(fakeTxID); reason(err) != ReasonUnknownTx {
473			t.Fatalf("fake tx id persisted: %v", err)
474		}
475	}
476	
477	// 尚未产生提议时 Proposal 始终返回不存在；读取本身不能创建候选或轮次记录，
478	// 不能把交易悄悄标记为已提议，也不能冻结一个空提议。之后首次 Propose
479	// 仍按当前交易池与既有打包规则正常产生提议。
480	func TestProposalAbsentBeforeProposeDoesNotCreateCandidate(t *testing.T) {
481		t.Run("with queued transactions", func(t *testing.T) {
482			keys := genKeys(t, 4)
483			n, _ := newTestNode(t, keys, 4)
484			tx := NewTransaction(keys[0].priv, 1, []byte("queued-before-propose"), 5, 100)
485			if _, err := n.Submit(tx); err != nil {
486				t.Fatal(err)
487			}
488	
489			// 多次读取都返回不存在。
490			for i := 0; i < 2; i++ {
491				if p, ok := n.Proposal(); ok {
492					t.Fatalf("Proposal must be absent before Propose (read %d): %+v", i+1, p)
493				}
494			}
495			// 读取没有创建轮次候选记录。
496			if _, err := n.Candidates(1); reason(err) != ReasonUnknownRound {
497				t.Fatalf("Candidates after absent read got %v, want %s", err, ReasonUnknownRound)
498			}
499			// 尚无提议期间登记候选仍按原规则拒绝。
500			if _, err := n.RegisterCandidate(1, []string{tx.ID()}); reason(err) != ReasonNoProposal {
501				t.Fatalf("register before Propose got %v, want %s", err, ReasonNoProposal)
502			}
503			// 交易仍在排队等待打包，没有被读取操作提议。
504			info, err := n.Tx(tx.ID())
505			if err != nil {
506				t.Fatal(err)
507			}
508			if info.Status != StatusQueued {
509				t.Fatalf("status after absent reads = %s, want %s", info.Status, StatusQueued)
510			}
511			assertAccountQueue(t, n, keys[0].pub, 0, map[string]string{tx.ID(): "waiting-pack"})
512	
513			// 之后首次 Propose 正常打包池内真实交易，空提议没有被提前冻结。
514			p, err := n.Propose()
515			if err != nil {
516				t.Fatal(err)
517			}
518			assertProposalView(t, p, 1, BlockID(1, 1, "", []string{tx.ID()}), []string{tx.ID()})
519		})
520	
521		t.Run("empty pool", func(t *testing.T) {
522			keys := genKeys(t, 4)
523			n, _ := newTestNode(t, keys, 4)
524			if _, ok := n.Proposal(); ok {
525				t.Fatal("Proposal must be absent on a fresh empty node")
526			}
527			if _, err := n.Candidates(1); reason(err) != ReasonUnknownRound {
528				t.Fatalf("Candidates on fresh node got %v, want %s", err, ReasonUnknownRound)
529			}
530			// 读取之后再 Propose，仍正常产生空块。
531			p, err := n.Propose()
532			if err != nil {
533				t.Fatal(err)
534			}
535			assertProposalView(t, p, 1, BlockID(1, 1, "", []string{}), []string{})
536		})
537	}
538	
539	// 提议结果是取得时的快照：第一轮取得结果并保留到进入第二轮后，它仍保留
540	// 取得时的轮次、区块标识与交易内容，不随节点当前提议变化；在新轮次编辑
541	// 这份旧结果，既改不了第一轮已确认的历史，也改不了当前轮的提议与候选，
542	// 当前轮查询与投票继续按已有规则进行。
543	func TestProposalResultIsSnapshotAcrossRounds(t *testing.T) {
544		keys := genKeys(t, 4)
545		n, _ := newTestNode(t, keys, 4)
546	
547		// 第一轮：乙1 费用 20 高于甲1 费用 10，提议顺序 [乙1, 甲1]。
548		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 10, 100)
549		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 20, 100)
550		for _, tx := range []*Transaction{a1, b1} {
551			if _, err := n.Submit(tx); err != nil {
552				t.Fatal(err)
553			}
554		}
555		want1 := []string{b1.ID(), a1.ID()}
556		first, err := n.Propose()
557		if err != nil {
558			t.Fatal(err)
559		}
560		id1 := BlockID(1, 1, "", want1)
561		assertProposalView(t, first, 1, id1, want1)
562	
563		confirmByVotes(t, n, keys, id1)
564		if n.CurrentRound() != 2 {
565			t.Fatalf("round after confirm = %d, want 2", n.CurrentRound())
566		}
567	
568		// 第二轮提交丙1 并产生新提议，区块接在第一轮确认块之后。
569		c1 := NewTransaction(keys[2].priv, 1, []byte("c1"), 5, 100)
570		if _, err := n.Submit(c1); err != nil {
571			t.Fatal(err)
572		}
573		want2 := []string{c1.ID()}
574		second, err := n.Propose()
575		if err != nil {
576			t.Fatal(err)
577		}
578		id2 := BlockID(2, 2, id1, want2)
579		assertProposalView(t, second, 2, id2, want2)
580	
581		// 第一轮取得后一直未编辑的结果，仍保留取得时的轮次、区块标识与交易顺序。
582		assertProposalView(t, first, 1, id1, want1)
583	
584		// 进入新轮次后才编辑旧结果：第一轮确认历史与当前轮提议、候选都不受影响。
585		tamperProposalView(&first)
586		again, ok := n.Proposal()
587		if !ok {
588			t.Fatal("round 2 Proposal should exist")
589		}
590		assertProposalView(t, again, 2, id2, want2)
591	
592		rc1, err := n.Candidates(1)
593		if err != nil {
594			t.Fatal(err)
595		}
596		if c := candidateByBlockID(rc1, id1); c == nil || c.Result != CandidateWon ||
597			fmt.Sprint(c.TxIDs) != fmt.Sprint(want1) {
598			t.Fatalf("round 1 winner history changed by stale edit: %+v", c)
599		}
600		rc2, err := n.Candidates(2)
601		if err != nil {
602			t.Fatal(err)
603		}
604		if c := candidateByBlockID(rc2, id2); c == nil || !c.Local || c.Result != CandidatePending ||
605			fmt.Sprint(c.TxIDs) != fmt.Sprint(want2) {
606			t.Fatalf("round 2 local candidate changed by stale edit: %+v", c)
607		}
608		if candidateByBlockID(rc2, fakeBlockID) != nil {
609			t.Fatal("fake block id from stale result must not register in round 2")
610		}
611		if _, err := n.Tx(fakeTxID); reason(err) != ReasonUnknownTx {
612			t.Fatalf("fake tx lookup got %v, want %s", err, ReasonUnknownTx)
613		}
614	
615		// 旧结果不能作为影响当前轮的入口：其中的轮次与区块标识投票按原规则拒绝。
616		if _, err := n.Vote(keys[0].pub, first.Round, first.BlockID); reason(err) != ReasonWrongRound {
617			t.Fatalf("vote with stale result got %v, want %s", err, ReasonWrongRound)
618		}
619	
620		// 当前轮凭真实标识投票确认，产生接在第一块之后的第二块；第一块保持原样。
621		confirmByVotes(t, n, keys, id2)
622		blk2, err := n.BlockAt(2)
623		if err != nil {
624			t.Fatal(err)
625		}
626		assertBlock(t, blk2, want2, 2, 2, id2, id1)
627		blk1, err := n.BlockAt(1)
628		if err != nil {
629			t.Fatal(err)
630		}
631		assertBlock(t, blk1, want1, 1, 1, id1, "")
632	
633		// 确认后进入第三轮，当前轮尚无提议：当前轮查询继续按已有规则返回，
634		// 旧轮结果保留在候选历史中，不被当作修改节点状态的入口。
635		if n.CurrentRound() != 3 {
636			t.Fatalf("round after second confirm = %d, want 3", n.CurrentRound())
637		}
638		if p, ok := n.Proposal(); ok {
639			t.Fatalf("new round must start without proposal, got %+v", p)
640		}
641		rc2End, err := n.Candidates(2)
642		if err != nil {
643			t.Fatal(err)
644		}
645		if c := candidateByBlockID(rc2End, id2); c == nil || c.Result != CandidateWon ||
646			fmt.Sprint(c.TxIDs) != fmt.Sprint(want2) {
647			t.Fatalf("round 2 winner history wrong after confirm: %+v", c)
648		}
649	}
