323		n.Submit(shared)
324		n.Submit(loserTx)
325		// 上限 10：本地提议同时包含两笔（顺序按打包规则，不影响本测试结论）。
326		local, _ := n.Propose()
327		if len(local.TxIDs) != 2 {
328			t.Fatalf("local proposal should pack both txs, got %v", local.TxIDs)
329		}
330		// 竞争候选只含 shared：它将胜出，loserTx 仅被落选的本地候选引用。
331		alt, err := n.RegisterCandidate(1, []string{shared.ID()})
332		if err != nil {
333			t.Fatal(err)
334		}
335		confirmCandidate(t, n, keys, alt.BlockID)
336	
337		// 共享交易只确认一次，关联胜出块；落选本地候选不能改变它。
338		info, _ := n.Tx(shared.ID())
339		if info.Status != StatusConfirmed || info.BlockID != alt.BlockID || info.BlockHeight != 1 {
340			t.Fatalf("shared tx wrong: %+v", info)
341		}
342		if a := n.Account(keys[0].pub); a.ConfirmedSequence != 1 {
343			t.Fatalf("winner account seq = %d, want 1", a.ConfirmedSequence)
344		}
345		// 落选候选独有的交易回到排队，账户序号不因落选推进。
346		loser, _ := n.Tx(loserTx.ID())
347		if loser.Status != StatusQueued {
348			t.Fatalf("loser-only tx status = %s, want queued", loser.Status)
349		}
350		if a := n.Account(keys[1].pub); a.ConfirmedSequence != 0 || len(a.Pending) != 1 {
351			t.Fatalf("loser account wrong: %+v", a)
352		}
353	
354		// 第 2 轮：再提交一笔进入轮次 3 即到期的交易；不确认直接结束。
355		expiring := NewTransaction(keys[3].priv, 1, []byte("expiring"), 1, 3)
356		n.Submit(expiring)
357		p2, _ := n.Propose()
358		if len(p2.TxIDs) != 2 {
359			t.Fatalf("round 2 proposal should pack loserTx and expiring, got %v", p2.TxIDs)
360		}
361		if r, err := n.EndRound(); err != nil || r != 3 {
362			t.Fatalf("end round = %d, %v", r, err)
363		}
364		if info, _ := n.Tx(expiring.ID()); info.Status != StatusExpired {
365			t.Fatalf("expiring tx status = %s, want expired", info.Status)
366		}
367		// 落选交易未到期则回到排队；已确认历史不变。
368		if info, _ := n.Tx(loserTx.ID()); info.Status != StatusQueued {
369			t.Fatalf("loser tx after EndRound = %s, want queued", info.Status)
370		}
371		if info, _ := n.Tx(shared.ID()); info.Status != StatusConfirmed {
372			t.Fatalf("confirmed tx changed after round end: %s", info.Status)
373		}
374		if n.Height() != 1 {
375			t.Fatal("EndRound must not create a block")
376		}
377		// 账户缺口与序号按实际确认结果：key1 的序号 1 仍在等待，无缺口。
378		if a := n.Account(keys[1].pub); a.Gap != 0 || a.ConfirmedSequence != 0 {
379			t.Fatalf("loser account after round end wrong: %+v", a)
380		}
381	}
